/workspace/.venv/bin/python - <<'PY'
import urllib.request, gzip, io, re
for comp in ["universe","main"]:
    u=f"http://archive.ubuntu.com/ubuntu/dists/noble/{comp}/binary-amd64/Packages.gz"
    try:
        data=urllib.request.urlopen(u, timeout=120).read()
        txt=gzip.decompress(data).decode(errors='replace')
        print("===",comp,len(txt))
        for block in txt.split("\n\n"):
            if block.startswith("Package: tesseract-ocr-eng\n") or block.startswith("Package: libtesseract5\n") or block.startswith("Package: libtesseract-dev\n"):
                for line in block.splitlines():
                    if line.startswith(("Package:","Version:","Filename:","Depends:")):
                        print(line)
                print("---")
    except Exception as e:
        print("ERR",comp,e)
PY
